int main(int argc,char**argv){try{bool flex=argc==2&&std::string(argv[1])=="--static-flex";if(argc>1&&!flex)throw std::runtime_error("invalid refresh test option");SessionTimelineDocumentCandidate doc(loadGraph("work/roundtrip-11.dmx"));std::filesystem::path content=R"(D:\SteamLibrary\steamapps\common\SourceFilmmaker\game\usermod)";std::ifstream file(content/"gameinfo.txt",std::ios::binary);std::string text((std::istreambuf_iterator<char>(file)),{});auto mounts=gameinfoMountsCandidate(text,content,content.parent_path());RetainedSessionSceneCandidate renderer(Graph(doc.graph()),2237,mounts,4,true,true);if(flex){auto provider=std::make_shared<RetainedStaticFlexProviderCandidate>(mounts);renderer.setBorrowedDeformationCandidate([provider](const Graph&graph,const SessionRenderModelCandidate&instance,const SfmModelGeometryCandidate&model)->const VvdGeometryCandidate&{return provider->sampleBorrowed(graph,instance,model);});}auto id=hierarchyRefs(doc.graph(),doc.graph().elements[2470],"timeFrame",1)[0];AnimationTimeFrame f(doc.graph(),doc.graph().elements[id]);int32_t tick=f.start+500;auto before=renderer.sample(tick);auto assetCount=renderer.assetCount(),materialCount=renderer.materialCount();doc.trimClipStart(2470,f.start+166);renderer.replaceSession(Graph(doc.graph()),2237);auto edited=renderer.sample(tick);compare(before,edited);doc.undo();renderer.replaceSession(Graph(doc.graph()),2237);compare(before,renderer.sample(tick));doc.redo();renderer.replaceSession(Graph(doc.graph()),2237);compare(before,renderer.sample(tick));if(renderer.assetCount()!=assetCount||renderer.materialCount()!=materialCount)throw std::runtime_error("cache growth after timeline edit");std::cout<<"static_flex="<<flex<<" document scene refresh passed trim undo redo vertices_camera_alpha_exact retained_material_identity=passed asset_cache_entries="<<assetCount<<" material_cache_entries="<<materialCount<<" tick="<<tick<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
